SELECT EXISTS (
    SELECT 1 FROM users
    WHERE email = #{email} AND user_id != #{userId}
)

SELECT EXISTS (
    SELECT 1 FROM users
    WHERE REPLACE(REPLACE(phone, '-', ''), ' ', '') = #{phoneDigits}
      AND user_id != #{userId}
)

SELECT EXISTS (
    SELECT 1 FROM users
    WHERE student_no = #{studentNo} AND user_id != #{userId}
)
